//! Acceptance cases owned by the calc-host package, each registered by its exact name in
//! `crates/calc-host/acceptance.json`. Every case is `#[test]` natively and `#[wasm_bindgen_test]`
//! on wasm32, with no browser or Node.js configuration of its own: `cargo xtask accept` forces the
//! browser with `WASM_BINDGEN_USE_BROWSER`.
//!
//! The cases drive the host only through its product route: `HostState::open` on package bytes,
//! `calc_host::dispatch`, `calc_host::step` and `calc_host::project`. The package is generated by
//! the test support module with no calc-doc code, with deliberately wrong formula caches. Every
//! expected input, value, provenance, revision, tick, dirty set, read and cycle below is derived by
//! hand from the fixture's literals and formula texts; none is read back from the host, a capture
//! or Excel.

// Case names are fixed identities of the form `<bead>__<case>`.
#![allow(non_snake_case)]

mod chost_m1_1_support;
mod dc_hqcv_support;

use calc_host::value::{
    CalcValue, CellKey, CoreValue, ExcelText, GridArea, NumericMode, NumericTargetId, SheetId,
};
use calc_host::{
    AuthoredRevision, CachedValue, CellEdit, CellError, CellInput, CellRun, CellText, CommandError,
    CommandReceipt, EditError, FileCached, FiniteNumber, FormulaText, HostCommand, HostOptions,
    HostProgress, HostState, LoadError, MemorySource, NotModeled, OpenFailure, OpenPolicy,
    PackageRead, ProjectedValue, ProjectionPage, ProjectionRequest, ReadObserver, RecalcContext,
    RecalcFailed, RecalcFailure, StaleCause, StartError, Unobserved, ValueChange, WorkBudget,
    dispatch, project, step,
};
use calc_verdict::CalculationContext;
use chost_m1_1_support::{CALC_PART, CALC_SHEET, INPUTS_SHEET, crc32, package, package_of};
use std::ops::ControlFlow;
use std::sync::Arc;

#[cfg(target_arch = "wasm32")]
use wasm_bindgen_test::wasm_bindgen_test;

/// Prints a line the acceptance runner keeps: on stdout natively, on the browser console (which
/// wasm-bindgen-test-runner forwards under `--nocapture`) on wasm32.
macro_rules! note {
    ($($arg:tt)*) => {{
        let line = format!($($arg)*);
        #[cfg(target_arch = "wasm32")]
        wasm_bindgen_test::console_log!("{}", line);
        #[cfg(not(target_arch = "wasm32"))]
        println!("{line}");
    }};
}

// ---------------------------------------------------------------------------------------------
// The workbook and how a case reads it.

/// The host of the fixture package, and its two sheets.
struct Book {
    host: HostState,
    inputs: SheetId,
    calc: SheetId,
}

impl Book {
    fn open(options: HostOptions) -> Book {
        let source: Arc<dyn PackageRead> = Arc::new(MemorySource::new(package()));
        let host = HostState::open(source, &OpenPolicy::default(), options)
            .expect("the fixture package opens");
        let sheet = |name: &str| {
            host.sheets()
                .iter()
                .find(|sheet| sheet.name().text().to_string_lossy() == name)
                .unwrap_or_else(|| panic!("the workbook holds the sheet {name}"))
                .id()
        };
        let (inputs, calc) = (sheet("Inputs"), sheet("Calc"));
        Book { host, inputs, calc }
    }

    /// The cell `a1` (one column letter and a row number) of `sheet`.
    fn at(&self, sheet: SheetId, a1: &str) -> CellKey {
        let column = u32::from(a1.as_bytes()[0] - b'A' + 1);
        let row: u32 = a1[1..].parse().expect("a row number");
        CellKey::new(sheet, row, column).expect("a cell inside the grid")
    }

    fn inputs(&self, a1: &str) -> CellKey {
        self.at(self.inputs, a1)
    }

    fn calc(&self, a1: &str) -> CellKey {
        self.at(self.calc, a1)
    }

    /// A1:C4 of Inputs, then A1:C4 of Calc, each row by row: every cell the fixture or a case
    /// fills, and empty cells around them.
    fn window(&self) -> ProjectionRequest {
        let mut cells = Vec::new();
        for sheet in [self.inputs, self.calc] {
            for row in 1..=4 {
                for column in 1..=3 {
                    cells.push(CellKey::new(sheet, row, column).unwrap());
                }
            }
        }
        ProjectionRequest { cells }
    }

    fn page(&self) -> ProjectionPage {
        let page = project(&self.host, &self.window()).expect("the window's sheets exist");
        assert_eq!(
            page.authored_revision(),
            page.engine_revision(),
            "the authored revision and the engine state are at one revision"
        );
        page
    }

    /// Each cell of the window with its value described, `"empty"` for an empty cell.
    fn described(&self) -> Vec<(CellKey, String)> {
        self.page()
            .cells()
            .iter()
            .map(|cell| (cell.at(), describe(cell.value())))
            .collect()
    }

    /// The window as `filled` describes it, every other cell `"empty"`.
    fn expected(&self, filled: &[(CellKey, String)]) -> Vec<(CellKey, String)> {
        self.window()
            .cells
            .iter()
            .map(|at| {
                let description = filled
                    .iter()
                    .find(|(cell, _)| cell == at)
                    .map(|(_, description)| description.clone())
                    .unwrap_or_else(|| "empty".to_owned());
                (*at, description)
            })
            .collect()
    }

    fn command(&self, base: u64, edits: Vec<CellEdit>) -> HostCommand {
        HostCommand {
            base: AuthoredRevision::new(base),
            edits,
        }
    }

    /// Dispatches the command of `edits` based on revision `base`.
    fn run(&mut self, base: u64, edits: Vec<CellEdit>) -> Result<CommandReceipt, CommandError> {
        let command = self.command(base, edits);
        dispatch(&mut self.host, command)
    }
}

fn number(value: f64) -> CellInput {
    CellInput::Number(FiniteNumber::new(value).unwrap())
}

fn formula(text: &str) -> CellInput {
    CellInput::Formula(FormulaText::new(ExcelText::from_interop_assignment(text)).unwrap())
}

fn text(text: &str) -> CellInput {
    CellInput::Text(CellText::new(ExcelText::from_interop_assignment(text)).unwrap())
}

fn set(at: CellKey, input: CellInput) -> CellEdit {
    CellEdit::Set { at, input }
}

fn shown(value: &CalcValue) -> String {
    match value.core() {
        CoreValue::Number(number) => format!("{number}"),
        CoreValue::Text(text) => format!("{:?}", text.to_string_lossy()),
        CoreValue::Logical(logical) => logical.to_string().to_uppercase(),
        CoreValue::Error(code) => format!("{code:?}"),
        other => format!("{other:?}"),
    }
}

fn cached(value: &CachedValue) -> String {
    match value {
        CachedValue::Number(number) => format!("{}", number.get()),
        CachedValue::Text(text) => format!("{:?}", text.text().to_string_lossy()),
        CachedValue::Logical(logical) => logical.to_string().to_uppercase(),
        CachedValue::Error(code) => format!("{code:?}"),
    }
}

fn mode(mode: &NumericMode) -> &'static str {
    match mode {
        NumericMode::Fast => "fast",
        NumericMode::Exact(_) => "exact",
    }
}

/// The name of the variant `debug` (a value's `{:?}`) starts with.
fn variant(debug: String) -> String {
    debug.chars().take_while(|c| c.is_alphanumeric()).collect()
}

/// A refusal by its kind: a compile or evaluation refusal by the name of CalcFml's variant.
fn refusal(refusal: &NotModeled) -> String {
    match refusal {
        NotModeled::Compile(error) => format!("compile {}", variant(format!("{error:?}"))),
        NotModeled::Evaluation(fault) => format!("evaluation {}", variant(format!("{fault:?}"))),
        other => format!("{other:?}"),
    }
}

/// A file cache: its value and the part, CRC-32 and size of its source.
fn cache_text(cache: &FileCached) -> String {
    format!(
        "file-cached {} from {} crc {:08x} size {}",
        cached(cache.value()),
        cache.source().name(),
        cache.source().crc32(),
        cache.source().size()
    )
}

/// A projected value as one line: its provenance first, then the value and the revision and tick
/// of the calculation it comes from.
fn describe(value: &ProjectedValue) -> String {
    match value {
        ProjectedValue::Empty => "empty".to_owned(),
        ProjectedValue::Literal(value) => format!("literal {}", shown(value)),
        ProjectedValue::FileCached(cache) => cache_text(cache),
        ProjectedValue::Calculated { value, calculation } => format!(
            "calculated {} r{} t{} {}",
            shown(value),
            calculation.revision().get(),
            calculation.tick().get(),
            mode(calculation.mode())
        ),
        ProjectedValue::NotModeled {
            refusal: why,
            calculation,
        } => format!(
            "not-modelled {} r{} t{}",
            refusal(why),
            calculation.revision().get(),
            calculation.tick().get()
        ),
        ProjectedValue::Stale(stale) => format!(
            "stale last {} {}{} {}",
            stale
                .last_value()
                .map(shown)
                .unwrap_or_else(|| "none".to_owned()),
            stale
                .last_calculation()
                .map(|calculation| format!(
                    "r{} t{}",
                    calculation.revision().get(),
                    calculation.tick().get()
                ))
                .unwrap_or_else(|| "none".to_owned()),
            stale
                .file_cache()
                .map(|cache| format!(" {}", cache_text(cache)))
                .unwrap_or_default(),
            match stale.cause() {
                StaleCause::AwaitingRecalc => "awaiting-recalc",
                StaleCause::RecalcFailed => "recalc-failed",
                StaleCause::FileCacheUnverified => "file-cache-unverified",
            }
        ),
    }
}

fn d(at: CellKey, description: &str) -> (CellKey, String) {
    (at, description.to_owned())
}

/// The cells each change of a published delta names, with `true` for a published result.
fn delta_cells(progress: &HostProgress) -> (u64, u64, Vec<(CellKey, bool)>) {
    match progress {
        HostProgress::Published(delta) => (
            delta.revision().get(),
            delta.tick().get(),
            delta
                .changes()
                .iter()
                .map(|change| match change {
                    ValueChange::Published { at, .. } => (*at, true),
                    ValueChange::Removed { at, .. } => (*at, false),
                })
                .collect(),
        ),
        other => panic!("the recalculation did not publish: {other:?}"),
    }
}

fn sorted(mut cells: Vec<CellKey>) -> Vec<CellKey> {
    cells.sort();
    cells
}

/// An observer that stops the recalculation at its `stop_at`-th observation (counting from 1) and
/// records where it stopped.
struct StopAt {
    observations: usize,
    stop_at: usize,
    stopped: Option<(CellKey, GridArea, u64)>,
}

impl StopAt {
    fn new(stop_at: usize) -> Self {
        StopAt {
            observations: 0,
            stop_at,
            stopped: None,
        }
    }
}

impl ReadObserver for StopAt {
    fn observe(
        &mut self,
        formula: CellKey,
        area: GridArea,
        offset: u64,
        _run: CellRun<'_>,
    ) -> ControlFlow<()> {
        self.observations += 1;
        if self.observations == self.stop_at {
            self.stopped = Some((formula, area, offset));
            return ControlFlow::Break(());
        }
        ControlFlow::Continue(())
    }
}

/// The description of a file cache the Calc sheet's part holds: the part name, and the CRC-32 and
/// size of the bytes the support module wrote for it.
fn file_cached(value: &str) -> String {
    format!(
        "file-cached {value} from {CALC_PART} crc {:08x} size {}",
        crc32(CALC_SHEET.as_bytes()),
        CALC_SHEET.len()
    )
}

/// The description of a stale value whose last published result is a file cache of the Calc
/// sheet's part.
fn stale_cache(value: &str, cause: &str) -> String {
    format!("stale last none none {} {cause}", file_cached(value))
}

/// The window of the fixture as it opens: each formula's cache projected as a file cache with the
/// identity of the part it was read from, and the formula the file cached nothing for as stale.
fn opened(book: &Book) -> Vec<(CellKey, String)> {
    book.expected(&[
        d(book.inputs("A1"), "literal 2"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), &file_cached("41")),
        d(book.calc("B1"), &file_cached("1")),
        d(book.calc("C1"), &file_cached("\"small\"")),
        d(book.calc("A2"), &file_cached("999")),
        d(book.calc("B2"), "stale last none none awaiting-recalc"),
        d(book.calc("A3"), &file_cached("7")),
    ])
}

// ---------------------------------------------------------------------------------------------
// chost_m1_1__atomic_prepare_failure

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test)]
fn chost_m1_1__atomic_prepare_failure() {
    const CASE: &str = "chost_m1_1__atomic_prepare_failure";
    note!(
        "ACCEPT-NOTE: {CASE}: every expected input, value, provenance, revision, tick and dirty set is derived by hand from the generated fixture's literals and formula texts; none is read back from the host, a capture or Excel"
    );

    // A package calc-doc refuses makes no host: bytes that are no archive, and a package whose
    // Inputs!A1 is a cell of type `d` (an ISO 8601 date), which the loader does not read.
    let refused = |bytes: Vec<u8>| {
        let source: Arc<dyn PackageRead> = Arc::new(MemorySource::new(bytes));
        HostState::open(source, &OpenPolicy::default(), HostOptions::default())
    };
    match refused(b"not a package".to_vec()) {
        Err(OpenFailure::Package(_)) => {}
        other => panic!("bytes that are no archive made a host: {other:?}"),
    }
    let dated = INPUTS_SHEET.replace(
        r#"<c r="A1"><v>2</v></c>"#,
        r#"<c r="A1" t="d"><v>2026-10-20</v></c>"#,
    );
    assert_ne!(dated, INPUTS_SHEET);
    assert_eq!(
        refused(package_of(&dated)).err(),
        Some(OpenFailure::Workbook(LoadError::Cell {
            part: "xl/worksheets/sheet1.xml".to_owned(),
            row: 1,
            column: 1,
            error: CellError::UnsupportedType {
                kind: "d".to_owned()
            },
        }))
    );

    // Six formula cells, and a budget of six.
    let mut book = Book::open(HostOptions {
        numeric: NumericMode::Fast,
        formula_cell_budget: Some(6),
    });

    // Before the first recalculation every cache is a file cache. A command with no edit is
    // refused before anything is prepared; a command is refused after both sides prepared, by the
    // host's formula-cell budget after the engine reserved the node for Calc!C2, which would make
    // seven formula cells against a budget of six. Neither changes a revision, an input or a file cache.
    assert_eq!(book.described(), opened(&book));
    let as_opened = book.page();
    assert_eq!(
        book.run(0, Vec::new()),
        Err(CommandError::NoEdits),
        "a command with no edit is refused"
    );
    assert_eq!(book.page(), as_opened);
    assert_eq!(
        book.run(
            0,
            vec![
                set(book.inputs("A1"), number(7.0)),
                set(book.calc("C2"), formula("Inputs!A1*2")),
            ]
        ),
        Err(CommandError::FormulaBudget {
            formula_cells: 7,
            budget: 6
        })
    );
    let still_opened = book.page();
    assert_eq!(still_opened.authored_revision(), AuthoredRevision::new(0));
    assert_eq!(
        still_opened, as_opened,
        "the refusal left revision 0 and every file cache standing"
    );
    note!(
        "ACCEPT-NOTE: {CASE}: before the first recalculation, a command with no edit and a command refused after the document side prepared left revision 0 and each of the five file caches projected as a file cache"
    );

    let first = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let (revision, tick, published) = delta_cells(&first);
    assert_eq!((revision, tick, published.len()), (0, 1, 6));

    let calculated = book.expected(&[
        d(book.inputs("A1"), "literal 2"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "calculated 5 r0 t1 fast"),
        d(
            book.calc("B1"),
            "not-modelled compile UnknownFunction r0 t1",
        ),
        d(book.calc("C1"), "calculated \"big\" r0 t1 fast"),
        d(book.calc("A2"), "calculated 50 r0 t1 fast"),
        d(book.calc("B2"), "calculated 2 r0 t1 fast"),
        d(book.calc("A3"), "calculated 2.5 r0 t1 fast"),
    ]);
    assert_eq!(book.described(), calculated);
    let before = book.page();
    assert_eq!(before.authored_revision(), AuthoredRevision::new(0));
    assert!(before.recalc_failure().is_none());

    // The document side refuses the batch: the formula "1+" is read with a diagnostic.
    let refused_by_document = book.command(
        0,
        vec![
            set(book.inputs("A1"), number(7.0)),
            set(book.calc("C2"), formula("1+")),
        ],
    );
    match dispatch(&mut book.host, refused_by_document) {
        Err(CommandError::Document(EditError::FormulaSyntax { operation, .. })) => {
            assert_eq!(operation, 1)
        }
        other => panic!("the document side did not refuse the formula: {other:?}"),
    }
    assert_eq!(book.page(), before, "a document refusal changed nothing");

    // The same command with a formula the document admits: the document side prepares the next
    // revision, the engine side reserves a node for Calc!C2, and the host's formula-cell budget
    // refuses it, because it would leave seven formula cells against a budget of six. The two commands differ
    // only in that formula's text, so the refusal came after the document side had prepared.
    let refused_after_document = book.command(
        0,
        vec![
            set(book.inputs("A1"), number(7.0)),
            set(book.calc("C2"), formula("Inputs!A1*2")),
        ],
    );
    assert_eq!(
        dispatch(&mut book.host, refused_after_document),
        Err(CommandError::FormulaBudget {
            formula_cells: 7,
            budget: 6
        })
    );
    let after = book.page();
    assert_eq!(after.authored_revision(), AuthoredRevision::new(0));
    assert_eq!(after.engine_revision(), AuthoredRevision::new(0));
    assert_eq!(
        after, before,
        "neither revision, no cell's input and no value or provenance changed: Inputs!A1 is still 2 and Calc!C2 still empty"
    );
    note!(
        "ACCEPT-NOTE: {CASE}: a refusal after the document side prepared (the host's formula-cell budget refused after the engine reserved the node) left the authored revision at 0, the engine at 0 and all 24 projected cells equal"
    );

    // A command based on another revision is refused before anything is prepared.
    let foreign_base = book.command(3, vec![set(book.inputs("A2"), number(9.0))]);
    assert_eq!(
        dispatch(&mut book.host, foreign_base),
        Err(CommandError::StaleBase {
            command: AuthoredRevision::new(3),
            current: AuthoredRevision::new(0)
        })
    );
    assert_eq!(book.page(), before);

    // Removing Calc!B1's formula while adding Calc!C2's keeps six formula cells, which the budget
    // admits. The failed commands left nothing behind: this one, based on revision 0 as they were,
    // makes revision 1.
    let admitted = book.command(
        0,
        vec![
            set(book.inputs("A1"), number(7.0)),
            CellEdit::Clear {
                area: GridArea::cell(book.calc("B1")),
            },
            set(book.calc("C2"), formula("Inputs!A1*2")),
        ],
    );
    let receipt = dispatch(&mut book.host, admitted).expect("the command commits");
    assert_eq!(receipt.base(), AuthoredRevision::new(0));
    assert_eq!(receipt.revision(), AuthoredRevision::new(1));
    assert_eq!(
        receipt.changed_cells(),
        sorted(vec![book.inputs("A1"), book.calc("C2")]).as_slice()
    );
    assert_eq!(receipt.cleared_areas(), &[GridArea::cell(book.calc("B1"))]);
    // Pending: the readers of Inputs!A1 (Calc!A1 and Calc!C1 by cell, Calc!A3 by the rectangle
    // Inputs!A1:A2) and the formula added at Calc!C2.
    assert_eq!(
        receipt.pending(),
        sorted(vec![
            book.calc("A1"),
            book.calc("C1"),
            book.calc("A3"),
            book.calc("C2")
        ])
        .as_slice()
    );
    assert_eq!(receipt.cancelled_recalc(), None);
    let committed = book.expected(&[
        d(book.inputs("A1"), "literal 7"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "stale last 5 r0 t1 awaiting-recalc"),
        d(book.calc("C1"), "stale last \"big\" r0 t1 awaiting-recalc"),
        d(book.calc("A2"), "stale last 50 r0 t1 awaiting-recalc"),
        d(book.calc("B2"), "calculated 2 r0 t1 fast"),
        d(book.calc("C2"), "stale last none none awaiting-recalc"),
        d(book.calc("A3"), "stale last 2.5 r0 t1 awaiting-recalc"),
    ]);
    assert_eq!(book.described(), committed);
    let committed_page = book.page();
    assert_eq!(committed_page.authored_revision(), AuthoredRevision::new(1));
    assert_eq!(
        committed_page.cells()[book
            .window()
            .cells
            .iter()
            .position(|at| *at == book.calc("C2"))
            .unwrap()]
        .input(),
        Some(&formula("Inputs!A1*2"))
    );

    // A retry based on revision 0 is now refused, and changes nothing.
    let stale_retry = book.command(0, vec![set(book.inputs("A2"), number(9.0))]);
    assert_eq!(
        dispatch(&mut book.host, stale_retry),
        Err(CommandError::StaleBase {
            command: AuthoredRevision::new(0),
            current: AuthoredRevision::new(1)
        })
    );
    assert_eq!(book.page(), committed_page);

    // The engine state the refusals left behind calculates the committed revision: Calc!A1 =
    // 7+3, Calc!A2 = 10*10, Calc!A3 = (7+3)*0.5, Calc!C2 = 7*2, Calc!C1 = "big" as 7>1; and the
    // result of the formula the command removed from Calc!B1 is removed.
    let second = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let (revision, tick, published) = delta_cells(&second);
    assert_eq!((revision, tick), (1, 2));
    let mut expected_changes: Vec<(CellKey, bool)> = [
        book.calc("A1"),
        book.calc("C1"),
        book.calc("A2"),
        book.calc("C2"),
        book.calc("A3"),
    ]
    .into_iter()
    .map(|at| (at, true))
    .chain([(book.calc("B1"), false)])
    .collect();
    expected_changes.sort();
    assert_eq!(published, expected_changes);
    assert_eq!(
        book.described(),
        book.expected(&[
            d(book.inputs("A1"), "literal 7"),
            d(book.inputs("B1"), "literal 0.5"),
            d(book.inputs("A2"), "literal 3"),
            d(book.inputs("A3"), "literal \"rate\""),
            d(book.calc("A1"), "calculated 10 r1 t2 fast"),
            d(book.calc("C1"), "calculated \"big\" r1 t2 fast"),
            d(book.calc("A2"), "calculated 100 r1 t2 fast"),
            d(book.calc("B2"), "calculated 2 r0 t1 fast"),
            d(book.calc("C2"), "calculated 14 r1 t2 fast"),
            d(book.calc("A3"), "calculated 5 r1 t2 fast"),
        ])
    );
}

// ---------------------------------------------------------------------------------------------
// chost_m1_1__recalc_failure_keeps_edit

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test)]
fn chost_m1_1__recalc_failure_keeps_edit() {
    const CASE: &str = "chost_m1_1__recalc_failure_keeps_edit";
    note!(
        "ACCEPT-NOTE: {CASE}: every expected input, value, provenance, revision, tick, dirty set, stopped read and cycle is derived by hand from the generated fixture's literals and formula texts; none is read back from the host, a capture or Excel, and agreement with Excel is infra-m1.3's round trip"
    );

    let mut book = Book::open(HostOptions::default());

    // Opened from package bytes: each formula's cache is projected as a file cache with the
    // identity of the part it was read from, and the formula the file cached nothing for as
    // stale. Nothing is calculated.
    assert_eq!(book.described(), opened(&book));
    let page = book.page();
    assert_eq!(page.authored_revision(), AuthoredRevision::new(0));
    assert!(
        page.cells()
            .iter()
            .all(|cell| !matches!(cell.value(), ProjectedValue::Calculated { .. })),
        "no cache loaded from the package is projected as calculated"
    );

    // The first recalculation replaces every cache with a calculated value or a typed refusal;
    // none of the calculated values equals the wrong cache it replaces.
    let first = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let (revision, tick, published) = delta_cells(&first);
    assert_eq!((revision, tick), (0, 1));
    assert_eq!(
        published,
        sorted(vec![
            book.calc("A1"),
            book.calc("B1"),
            book.calc("C1"),
            book.calc("A2"),
            book.calc("B2"),
            book.calc("A3"),
        ])
        .into_iter()
        .map(|at| (at, true))
        .collect::<Vec<_>>()
    );
    let calculated = book.expected(&[
        d(book.inputs("A1"), "literal 2"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "calculated 5 r0 t1 fast"),
        d(
            book.calc("B1"),
            "not-modelled compile UnknownFunction r0 t1",
        ),
        d(book.calc("C1"), "calculated \"big\" r0 t1 fast"),
        d(book.calc("A2"), "calculated 50 r0 t1 fast"),
        d(book.calc("B2"), "calculated 2 r0 t1 fast"),
        d(book.calc("A3"), "calculated 2.5 r0 t1 fast"),
    ]);
    assert_eq!(book.described(), calculated);
    let page = book.page();
    let b1 = page
        .cells()
        .iter()
        .find(|cell| cell.at() == book.calc("B1"))
        .unwrap();
    match b1.value() {
        ProjectedValue::NotModeled {
            refusal: NotModeled::Compile(error),
            ..
        } => assert!(format!("{error:?}").contains("spelling: \"NOSUCHFUNCTION\"")),
        other => panic!("Calc!B1 is not refused: {other:?}"),
    }
    assert_eq!(
        step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved),
        HostProgress::Current
    );

    // An edit: Inputs!A1 = 10. Its readers (Calc!A1 and Calc!C1 by cell, Calc!A3 by the rectangle
    // Inputs!A1:A2) are pending, and Calc!A2, which reads Calc!A1, is stale with them.
    let receipt = book
        .run(0, vec![set(book.inputs("A1"), number(10.0))])
        .expect("the edit commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(1));
    assert_eq!(receipt.changed_cells(), &[book.inputs("A1")]);
    assert!(receipt.cleared_areas().is_empty());
    assert_eq!(
        receipt.pending(),
        sorted(vec![book.calc("A1"), book.calc("C1"), book.calc("A3")]).as_slice()
    );
    let awaiting = book.expected(&[
        d(book.inputs("A1"), "literal 10"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "stale last 5 r0 t1 awaiting-recalc"),
        d(
            book.calc("B1"),
            "not-modelled compile UnknownFunction r0 t1",
        ),
        d(book.calc("C1"), "stale last \"big\" r0 t1 awaiting-recalc"),
        d(book.calc("A2"), "stale last 50 r0 t1 awaiting-recalc"),
        d(book.calc("B2"), "calculated 2 r0 t1 fast"),
        d(book.calc("A3"), "stale last 2.5 r0 t1 awaiting-recalc"),
    ]);
    assert_eq!(book.described(), awaiting);

    // The recalculation fails: the observer stops its first read. The closure is ordered by a
    // ready queue on the cells' order, so Calc!A1 is evaluated first, and its first read is its
    // left operand, Inputs!A1.
    let mut stop = StopAt::new(1);
    let failed = step(&mut book.host, WorkBudget::UNLIMITED, &mut stop);
    let expected_failure = RecalcFailed::Failed(RecalcFailure::ReadFailed {
        formula: book.calc("A1"),
        area: GridArea::cell(book.inputs("A1")),
    });
    assert_eq!(failed, HostProgress::Failed(expected_failure.clone()));
    assert_eq!(
        stop.stopped,
        Some((book.calc("A1"), GridArea::cell(book.inputs("A1")), 0))
    );
    // The edit stays at revision 1; the results it left stale are still projected as stale, now
    // because the recalculation failed, and never as calculated.
    let after_failure = book.expected(&[
        d(book.inputs("A1"), "literal 10"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "stale last 5 r0 t1 recalc-failed"),
        d(
            book.calc("B1"),
            "not-modelled compile UnknownFunction r0 t1",
        ),
        d(book.calc("C1"), "stale last \"big\" r0 t1 recalc-failed"),
        d(book.calc("A2"), "stale last 50 r0 t1 recalc-failed"),
        d(book.calc("B2"), "calculated 2 r0 t1 fast"),
        d(book.calc("A3"), "stale last 2.5 r0 t1 recalc-failed"),
    ]);
    assert_eq!(book.described(), after_failure);
    let page = book.page();
    assert_eq!(page.authored_revision(), AuthoredRevision::new(1));
    assert_eq!(page.recalc_failure(), Some(&expected_failure));
    note!(
        "ACCEPT-NOTE: {CASE}: after the stopped read the edit Inputs!A1 = 10 is at revision 1 and Calc!A1, C1, A2, A3 project their tick-1 values as stale, not calculated"
    );
    // A refused command commits nothing, so the failed recalculation is still the last one of the
    // current revision.
    assert_eq!(
        book.run(0, vec![set(book.inputs("A2"), number(4.0))]),
        Err(CommandError::StaleBase {
            command: AuthoredRevision::new(0),
            current: AuthoredRevision::new(1)
        })
    );
    assert_eq!(book.described(), after_failure);

    // A second edit makes a circular reference: Inputs!A2 = Calc!A2, which reads Calc!A1, which
    // reads Inputs!A2. The engine refuses to begin: the cycle's cells and Calc!A3, which reads
    // Inputs!A2 through Inputs!A1:A2, cannot be ordered; Calc!C1 reads only the literal Inputs!A1.
    let receipt = book
        .run(1, vec![set(book.inputs("A2"), formula("Calc!A2"))])
        .expect("a circular reference is authored like any formula");
    assert_eq!(receipt.revision(), AuthoredRevision::new(2));
    assert_eq!(receipt.changed_cells(), &[book.inputs("A2")]);
    assert_eq!(
        receipt.pending(),
        sorted(vec![
            book.inputs("A2"),
            book.calc("A1"),
            book.calc("C1"),
            book.calc("A3")
        ])
        .as_slice()
    );
    // The commit returns every stale cell to awaiting a recalculation of revision 2, the formula
    // it added at Inputs!A2 included; the failure is still the last recalculation's.
    let committed_after_failure = book.expected(&[
        d(book.inputs("A1"), "literal 10"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "stale last none none awaiting-recalc"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "stale last 5 r0 t1 awaiting-recalc"),
        d(
            book.calc("B1"),
            "not-modelled compile UnknownFunction r0 t1",
        ),
        d(book.calc("C1"), "stale last \"big\" r0 t1 awaiting-recalc"),
        d(book.calc("A2"), "stale last 50 r0 t1 awaiting-recalc"),
        d(book.calc("B2"), "calculated 2 r0 t1 fast"),
        d(book.calc("A3"), "stale last 2.5 r0 t1 awaiting-recalc"),
    ]);
    assert_eq!(book.described(), committed_after_failure);
    assert_eq!(book.page().recalc_failure(), Some(&expected_failure));
    let refused = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let expected_refusal = RecalcFailed::Refused(StartError::Cycle {
        cells: sorted(vec![
            book.inputs("A2"),
            book.calc("A1"),
            book.calc("A2"),
            book.calc("A3"),
        ]),
    });
    assert_eq!(refused, HostProgress::Failed(expected_refusal.clone()));
    let cycle = book.expected(&[
        d(book.inputs("A1"), "literal 10"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "stale last none none recalc-failed"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "stale last 5 r0 t1 recalc-failed"),
        d(
            book.calc("B1"),
            "not-modelled compile UnknownFunction r0 t1",
        ),
        d(book.calc("C1"), "stale last \"big\" r0 t1 recalc-failed"),
        d(book.calc("A2"), "stale last 50 r0 t1 recalc-failed"),
        d(book.calc("B2"), "calculated 2 r0 t1 fast"),
        d(book.calc("A3"), "stale last 2.5 r0 t1 recalc-failed"),
    ]);
    assert_eq!(book.described(), cycle);
    let page = book.page();
    assert_eq!(page.authored_revision(), AuthoredRevision::new(2));
    assert_eq!(page.recalc_failure(), Some(&expected_refusal));

    // Breaking the cycle: Inputs!A2 = 3 again. The next recalculation calculates the edit both
    // failures kept: Calc!A1 = 10+3, Calc!A2 = 13*10, Calc!A3 = (10+3)*0.5. It takes tick 3: the
    // stopped recalculation used tick 2, and the refused one began none.
    let receipt = book
        .run(2, vec![set(book.inputs("A2"), number(3.0))])
        .expect("the edit commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(3));
    assert_eq!(
        receipt.pending(),
        sorted(vec![book.calc("A1"), book.calc("C1"), book.calc("A3")]).as_slice()
    );
    let published = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let (revision, tick, changes) = delta_cells(&published);
    assert_eq!((revision, tick), (3, 3));
    assert_eq!(
        changes,
        sorted(vec![
            book.calc("A1"),
            book.calc("C1"),
            book.calc("A2"),
            book.calc("A3"),
        ])
        .into_iter()
        .map(|at| (at, true))
        .collect::<Vec<_>>()
    );
    assert_eq!(
        book.described(),
        book.expected(&[
            d(book.inputs("A1"), "literal 10"),
            d(book.inputs("B1"), "literal 0.5"),
            d(book.inputs("A2"), "literal 3"),
            d(book.inputs("A3"), "literal \"rate\""),
            d(book.calc("A1"), "calculated 13 r3 t3 fast"),
            d(
                book.calc("B1"),
                "not-modelled compile UnknownFunction r0 t1"
            ),
            d(book.calc("C1"), "calculated \"big\" r3 t3 fast"),
            d(book.calc("A2"), "calculated 130 r3 t3 fast"),
            d(book.calc("B2"), "calculated 2 r0 t1 fast"),
            d(book.calc("A3"), "calculated 6.5 r3 t3 fast"),
        ])
    );
    assert!(book.page().recalc_failure().is_none());

    // A recalculation in progress is cancelled by an edit that commits during it, and nothing it
    // staged is published: Inputs!B1 = 1 leaves Calc!B2 and Calc!A3 pending; a step of one
    // evaluation (tick 4) evaluates Calc!B2 first; then Inputs!A1 = 20 commits.
    book.run(3, vec![set(book.inputs("B1"), number(1.0))])
        .expect("the edit commits");
    assert_eq!(
        step(&mut book.host, WorkBudget::evaluations(1), &mut Unobserved),
        HostProgress::Calculating { remaining: 1 }
    );
    let receipt = book
        .run(4, vec![set(book.inputs("A1"), number(20.0))])
        .expect("the edit commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(5));
    assert_eq!(receipt.cancelled_recalc().map(|tick| tick.get()), Some(4));
    assert_eq!(
        receipt.pending(),
        sorted(vec![
            book.calc("A1"),
            book.calc("C1"),
            book.calc("B2"),
            book.calc("A3")
        ])
        .as_slice()
    );
    let cancelled = book.page();
    let b2 = cancelled
        .cells()
        .iter()
        .find(|cell| cell.at() == book.calc("B2"))
        .unwrap();
    assert_eq!(
        describe(b2.value()),
        "stale last 2 r0 t1 awaiting-recalc",
        "the value tick 4 staged for Calc!B2 was never published"
    );
    // Calc!A1 = 20+3, Calc!A2 = 23*10, Calc!A3 = (20+3)*1, Calc!B2 = 1*4, at tick 5.
    let published = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let (revision, tick, _) = delta_cells(&published);
    assert_eq!((revision, tick), (5, 5));
    assert_eq!(
        book.described(),
        book.expected(&[
            d(book.inputs("A1"), "literal 20"),
            d(book.inputs("B1"), "literal 1"),
            d(book.inputs("A2"), "literal 3"),
            d(book.inputs("A3"), "literal \"rate\""),
            d(book.calc("A1"), "calculated 23 r5 t5 fast"),
            d(
                book.calc("B1"),
                "not-modelled compile UnknownFunction r0 t1"
            ),
            d(book.calc("C1"), "calculated \"big\" r5 t5 fast"),
            d(book.calc("A2"), "calculated 230 r5 t5 fast"),
            d(book.calc("B2"), "calculated 4 r5 t5 fast"),
            d(book.calc("A3"), "calculated 23 r5 t5 fast"),
        ])
    );
    assert_eq!(
        step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved),
        HostProgress::Current
    );

    edits_before_the_first_recalculation(CASE);
}

/// The second part of chost_m1_1__recalc_failure_keeps_edit, on a host opened again from the same
/// bytes: edits committed before any recalculation, then a first recalculation that fails, then
/// one that publishes, then an edit to an input a refused formula reads.
fn edits_before_the_first_recalculation(case: &str) {
    // A first recalculation that fails, with no edit before it, leaves every file cache standing:
    // the observer stops its first read, Calc!A1's read of Inputs!A1 (Calc!A1 is the first ready
    // formula in cell order). Only the formula the file cached nothing for is stale, now because
    // the recalculation of revision 0 failed.
    let mut unedited = Book::open(HostOptions::default());
    let mut stop = StopAt::new(1);
    assert_eq!(
        step(&mut unedited.host, WorkBudget::UNLIMITED, &mut stop),
        HostProgress::Failed(RecalcFailed::Failed(RecalcFailure::ReadFailed {
            formula: unedited.calc("A1"),
            area: GridArea::cell(unedited.inputs("A1")),
        }))
    );
    let mut failed_unedited = opened(&unedited);
    let b2 = failed_unedited
        .iter_mut()
        .find(|(at, _)| *at == unedited.calc("B2"))
        .unwrap();
    b2.1 = "stale last none none recalc-failed".to_owned();
    assert_eq!(unedited.described(), failed_unedited);

    let mut book = Book::open(HostOptions::default());
    assert_eq!(book.described(), opened(&book));

    // A command that sets Inputs!A3 to the text it holds commits revision 1 and changes no input
    // or formula, so every file cache still stands. Every node of a newly opened workbook is
    // pending.
    let receipt = book
        .run(0, vec![set(book.inputs("A3"), text("rate"))])
        .expect("the command commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(1));
    assert!(receipt.changed_cells().is_empty());
    assert!(receipt.cleared_areas().is_empty());
    assert_eq!(
        receipt.pending(),
        sorted(vec![
            book.calc("A1"),
            book.calc("B1"),
            book.calc("C1"),
            book.calc("A2"),
            book.calc("B2"),
            book.calc("A3"),
        ])
        .as_slice()
    );
    assert_eq!(book.described(), opened(&book));

    // Revision 2 replaces Calc!A1's formula and clears Calc!C1. Calc!A1's cache is the result of
    // a formula the cell no longer holds: stale, awaiting a recalculation. No formula is bound
    // yet, so the engine cannot say which other caches the edit reached: each of them (Calc!A2
    // reads Calc!A1; Calc!B1 and Calc!A3 read nothing the edit changed) is stale as unverified.
    let receipt = book
        .run(
            1,
            vec![
                set(book.calc("A1"), formula("Inputs!B1*100")),
                CellEdit::Clear {
                    area: GridArea::cell(book.calc("C1")),
                },
            ],
        )
        .expect("the edit commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(2));
    assert_eq!(receipt.changed_cells(), &[book.calc("A1")]);
    assert_eq!(receipt.cleared_areas(), &[GridArea::cell(book.calc("C1"))]);
    assert_eq!(
        receipt.pending(),
        sorted(vec![
            book.calc("A1"),
            book.calc("B1"),
            book.calc("A2"),
            book.calc("B2"),
            book.calc("A3"),
        ])
        .as_slice()
    );
    assert_eq!(
        book.described(),
        book.expected(&[
            d(book.inputs("A1"), "literal 2"),
            d(book.inputs("B1"), "literal 0.5"),
            d(book.inputs("A2"), "literal 3"),
            d(book.inputs("A3"), "literal \"rate\""),
            d(book.calc("A1"), &stale_cache("41", "awaiting-recalc")),
            d(book.calc("B1"), &stale_cache("1", "file-cache-unverified")),
            d(
                book.calc("A2"),
                &stale_cache("999", "file-cache-unverified")
            ),
            d(book.calc("B2"), "stale last none none awaiting-recalc"),
            d(book.calc("A3"), &stale_cache("7", "file-cache-unverified")),
        ])
    );

    // Revision 3 authors a new formula in the cleared Calc!C1, sets Inputs!A1 (which Calc!A3
    // reads through Inputs!A1:A2) and adds Calc!C2, which reads the refused Calc!B1 and Inputs!A1.
    // Calc!C1's new formula is not the one whose cache is still published there.
    let receipt = book
        .run(
            2,
            vec![
                set(book.calc("C1"), formula("Inputs!A1*3")),
                set(book.inputs("A1"), number(10.0)),
                set(book.calc("C2"), formula("B1+Inputs!A1")),
            ],
        )
        .expect("the edit commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(3));
    assert_eq!(
        receipt.changed_cells(),
        sorted(vec![book.inputs("A1"), book.calc("C1"), book.calc("C2")]).as_slice()
    );
    let unbound_edits = book.expected(&[
        d(book.inputs("A1"), "literal 10"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), &stale_cache("41", "awaiting-recalc")),
        d(book.calc("B1"), &stale_cache("1", "file-cache-unverified")),
        d(
            book.calc("C1"),
            &stale_cache("\"small\"", "awaiting-recalc"),
        ),
        d(
            book.calc("A2"),
            &stale_cache("999", "file-cache-unverified"),
        ),
        d(book.calc("B2"), "stale last none none awaiting-recalc"),
        d(book.calc("C2"), "stale last none none awaiting-recalc"),
        d(book.calc("A3"), &stale_cache("7", "file-cache-unverified")),
    ]);
    assert_eq!(book.described(), unbound_edits);
    let page = book.page();
    assert!(
        page.cells().iter().all(|cell| !matches!(
            cell.value(),
            ProjectedValue::FileCached(_) | ProjectedValue::Calculated { .. }
        )),
        "after the edits no cache is projected as a file cache that stands, and nothing as calculated"
    );
    note!(
        "ACCEPT-NOTE: {case}: before any recalculation, a replaced formula (Calc!A1), a formula cleared and replaced by a different one (Calc!C1) and the formulas reading an edited cell (Calc!A3 reads Inputs!A1, Calc!A2 reads Calc!A1) project their file caches as stale, never as file caches; at revision 3 three cells carry the cause file-cache-unverified, which the host gives every as-opened file cache once an edit changed an input, without the engine's reach: Calc!A2 and Calc!A3, which the edits reached, and Calc!B1, which no edit reached (at revision 2 Calc!A3, not yet reached, carried it as well), the conservative broadening dc-f92f is to retire"
    );

    // The first recalculation fails: the observer stops its first read, Calc!A1's read of
    // Inputs!B1 (Calc!A1 is the first ready formula in cell order). The edits stay at revision 3,
    // and the caches of the formulas it would have calculated stay stale.
    let mut stop = StopAt::new(1);
    let failed = step(&mut book.host, WorkBudget::UNLIMITED, &mut stop);
    let expected_failure = RecalcFailed::Failed(RecalcFailure::ReadFailed {
        formula: book.calc("A1"),
        area: GridArea::cell(book.inputs("B1")),
    });
    assert_eq!(failed, HostProgress::Failed(expected_failure.clone()));
    assert_eq!(
        stop.stopped,
        Some((book.calc("A1"), GridArea::cell(book.inputs("B1")), 0))
    );
    assert_eq!(
        book.described(),
        book.expected(&[
            d(book.inputs("A1"), "literal 10"),
            d(book.inputs("B1"), "literal 0.5"),
            d(book.inputs("A2"), "literal 3"),
            d(book.inputs("A3"), "literal \"rate\""),
            d(book.calc("A1"), &stale_cache("41", "recalc-failed")),
            d(book.calc("B1"), &stale_cache("1", "file-cache-unverified")),
            d(book.calc("C1"), &stale_cache("\"small\"", "recalc-failed")),
            d(
                book.calc("A2"),
                &stale_cache("999", "file-cache-unverified")
            ),
            d(book.calc("B2"), "stale last none none recalc-failed"),
            d(book.calc("C2"), "stale last none none recalc-failed"),
            d(book.calc("A3"), &stale_cache("7", "file-cache-unverified")),
        ])
    );
    let page = book.page();
    assert_eq!(page.authored_revision(), AuthoredRevision::new(3));
    assert_eq!(page.recalc_failure(), Some(&expected_failure));
    let input = |at: CellKey| {
        page.cells()
            .iter()
            .find(|cell| cell.at() == at)
            .and_then(|cell| cell.input())
            .cloned()
    };
    assert_eq!(input(book.calc("A1")), Some(formula("Inputs!B1*100")));
    assert_eq!(input(book.calc("C1")), Some(formula("Inputs!A1*3")));
    assert_eq!(input(book.calc("C2")), Some(formula("B1+Inputs!A1")));

    // The next recalculation (tick 2; the failed one used tick 1) calculates every formula of
    // revision 3: Calc!A1 = 0.5*100, Calc!C1 = 10*3, Calc!A2 = 50*10, Calc!B2 = 0.5*4, Calc!A3 =
    // (10+3)*0.5; Calc!B1 is refused at compile time and Calc!C2, reading it, at evaluation.
    let published = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let (revision, tick, changes) = delta_cells(&published);
    assert_eq!((revision, tick), (3, 2));
    assert_eq!(
        changes,
        sorted(vec![
            book.calc("A1"),
            book.calc("B1"),
            book.calc("C1"),
            book.calc("A2"),
            book.calc("B2"),
            book.calc("C2"),
            book.calc("A3"),
        ])
        .into_iter()
        .map(|at| (at, true))
        .collect::<Vec<_>>()
    );
    let calculated = book.expected(&[
        d(book.inputs("A1"), "literal 10"),
        d(book.inputs("B1"), "literal 0.5"),
        d(book.inputs("A2"), "literal 3"),
        d(book.inputs("A3"), "literal \"rate\""),
        d(book.calc("A1"), "calculated 50 r3 t2 fast"),
        d(
            book.calc("B1"),
            "not-modelled compile UnknownFunction r3 t2",
        ),
        d(book.calc("C1"), "calculated 30 r3 t2 fast"),
        d(book.calc("A2"), "calculated 500 r3 t2 fast"),
        d(book.calc("B2"), "calculated 2 r3 t2 fast"),
        d(
            book.calc("C2"),
            "not-modelled evaluation MissingInput r3 t2",
        ),
        d(book.calc("A3"), "calculated 6.5 r3 t2 fast"),
    ]);
    assert_eq!(book.described(), calculated);
    let page = book.page();
    let c2 = page
        .cells()
        .iter()
        .find(|cell| cell.at() == book.calc("C2"))
        .unwrap();
    match c2.value() {
        ProjectedValue::NotModeled {
            refusal: NotModeled::Evaluation(fault),
            ..
        } => assert_eq!(
            format!("{fault:?}"),
            format!("MissingInput {{ cell: {:?} }}", book.calc("B1")),
            "Calc!C2 is refused for reading the refused Calc!B1"
        ),
        other => panic!("Calc!C2 is not refused at evaluation: {other:?}"),
    }

    // Inputs!A1 = 20: its readers Calc!C1, Calc!C2 and Calc!A3 are pending, and the refusal of
    // Calc!C2, which reads it, is stale like the values of the others.
    let receipt = book
        .run(3, vec![set(book.inputs("A1"), number(20.0))])
        .expect("the edit commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(4));
    assert_eq!(
        receipt.pending(),
        sorted(vec![book.calc("C1"), book.calc("C2"), book.calc("A3")]).as_slice()
    );
    assert_eq!(
        book.described(),
        book.expected(&[
            d(book.inputs("A1"), "literal 20"),
            d(book.inputs("B1"), "literal 0.5"),
            d(book.inputs("A2"), "literal 3"),
            d(book.inputs("A3"), "literal \"rate\""),
            d(book.calc("A1"), "calculated 50 r3 t2 fast"),
            d(
                book.calc("B1"),
                "not-modelled compile UnknownFunction r3 t2",
            ),
            d(book.calc("C1"), "stale last 30 r3 t2 awaiting-recalc"),
            d(book.calc("A2"), "calculated 500 r3 t2 fast"),
            d(book.calc("B2"), "calculated 2 r3 t2 fast"),
            d(book.calc("C2"), "stale last none r3 t2 awaiting-recalc"),
            d(book.calc("A3"), "stale last 6.5 r3 t2 awaiting-recalc"),
        ])
    );

    // Calc!C1 = 20*3 and Calc!A3 = (20+3)*0.5 at tick 3; Calc!C2 is refused again.
    let published = step(&mut book.host, WorkBudget::UNLIMITED, &mut Unobserved);
    let (revision, tick, changes) = delta_cells(&published);
    assert_eq!((revision, tick), (4, 3));
    assert_eq!(
        changes,
        sorted(vec![book.calc("C1"), book.calc("C2"), book.calc("A3")])
            .into_iter()
            .map(|at| (at, true))
            .collect::<Vec<_>>()
    );
    assert_eq!(
        book.described(),
        book.expected(&[
            d(book.inputs("A1"), "literal 20"),
            d(book.inputs("B1"), "literal 0.5"),
            d(book.inputs("A2"), "literal 3"),
            d(book.inputs("A3"), "literal \"rate\""),
            d(book.calc("A1"), "calculated 50 r3 t2 fast"),
            d(
                book.calc("B1"),
                "not-modelled compile UnknownFunction r3 t2",
            ),
            d(book.calc("C1"), "calculated 60 r4 t3 fast"),
            d(book.calc("A2"), "calculated 500 r3 t2 fast"),
            d(book.calc("B2"), "calculated 2 r3 t2 fast"),
            d(
                book.calc("C2"),
                "not-modelled evaluation MissingInput r4 t3",
            ),
            d(book.calc("A3"), "calculated 11.5 r4 t3 fast"),
        ])
    );
}

// ---------------------------------------------------------------------------------------------
// dc_hqcv__applied_context_reported

/// The cell `a1` (one column letter and a row number) of `sheet`.
fn cell(sheet: SheetId, a1: &str) -> CellKey {
    let column = u32::from(a1.as_bytes()[0] - b'A' + 1);
    let row: u32 = a1[1..].parse().expect("a row number");
    CellKey::new(sheet, row, column).expect("a cell inside the grid")
}

/// The `workbookPr` element of the workbook part the package `bytes` stores, and its `calcPr`
/// element (`None` when the part names no `calcPr` at all), read from the stored bytes.
fn declared_elements(bytes: &[u8]) -> (String, Option<String>) {
    let part = dc_hqcv_support::stored_entry(bytes, "xl/workbook.xml")
        .expect("the package stores its workbook part uncompressed");
    let part = std::str::from_utf8(part).expect("the workbook part is UTF-8");
    let workbook_pr = dc_hqcv_support::empty_element(part, "workbookPr")
        .expect("the workbook part holds workbookPr")
        .to_owned();
    let calc_pr = part.contains("calcPr").then(|| {
        dc_hqcv_support::empty_element(part, "calcPr")
            .expect("the workbook part's calcPr is an empty element")
            .to_owned()
    });
    (workbook_pr, calc_pr)
}

/// The host of the package `bytes`, opened with `options`, and its one sheet's ID.
fn open_package(bytes: Vec<u8>, options: HostOptions) -> (HostState, SheetId) {
    let source: Arc<dyn PackageRead> = Arc::new(MemorySource::new(bytes));
    let host = HostState::open(source, &OpenPolicy::default(), options)
        .expect("the dc-hqcv package opens");
    let sheet = host.sheets()[0].id();
    (host, sheet)
}

/// A1:B3 of `sheet`, row by row, each cell's value described.
fn described_a1_b3(host: &HostState, sheet: SheetId) -> Vec<(String, String)> {
    let names = ["A1", "B1", "A2", "B2", "A3", "B3"];
    let request = ProjectionRequest {
        cells: names.iter().map(|a1| cell(sheet, a1)).collect(),
    };
    let page = project(host, &request).expect("the sheet exists");
    assert_eq!(page.authored_revision(), page.engine_revision());
    names
        .iter()
        .zip(page.cells())
        .map(|(a1, projected)| ((*a1).to_owned(), describe(projected.value())))
        .collect()
}

fn context_text(context: &RecalcContext) -> String {
    format!(
        "date1904={} iteration={} precision_as_displayed={} numeric={}",
        context.date1904,
        context.iteration,
        context.precision_as_displayed,
        mode(&context.numeric)
    )
}

/// The verdict library's context fingerprint of a run under `context`, built from `context` and
/// nothing else. The host reports no iteration count or maximum change, so a context with
/// iteration on is refused here: its fingerprint would need limits from outside the host.
fn run_fingerprint(context: &RecalcContext) -> String {
    assert!(
        !context.iteration,
        "the host applies iteration but reports no iteration limits, so the run's context \
         fingerprint cannot come from the host alone"
    );
    CalculationContext::without_iteration(context.date1904, context.precision_as_displayed)
        .fingerprint()
}

/// A package whose workbook part declares the 1904 date system (`workbookPr date1904="1"`),
/// iterative calculation (`calcPr iterate="1"`) and precision as displayed
/// (`calcPr fullPrecision="0"`), as the case reads them from the generated bytes, opens through
/// HostState::open and reports the context its recalculation applies: the 1900 date system, no
/// iteration and full precision, under the numeric mode the host was opened with. The verdict
/// library's context fingerprint of the run is built from that report alone. The host reports the
/// date system the package declares, which calc-doc reads; it has no record of the calcPr
/// settings, which calc-doc does not read. One of the applied values is also observed in what the
/// host calculates: the circular reference B1 = B1+1 is refused, not iterated. A2 and A3 are
/// published at full precision, which does not tell full precision from precision as displayed
/// while calc-doc reads no number format, and the date system is not observed. A second package,
/// the same with no calcPr in its stored workbook part, under an Exact numeric mode, reports the
/// same applied settings, the same fingerprint and that mode.
#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test)]
fn dc_hqcv__applied_context_reported() {
    const CASE: &str = "dc_hqcv__applied_context_reported";
    let applied = RecalcContext {
        date1904: false,
        iteration: false,
        precision_as_displayed: false,
        numeric: NumericMode::Fast,
    };
    // A context in the 1900 date system, without iteration and at full precision, as the verdict
    // library names it: iteration off names Excel's default limits, 100 iterations and a maximum
    // change of 0.001 (binary64 bits 3f50624dd2f1a9fc).
    let applied_fingerprint = "excel-calc-context/1;date1904=false;iteration=false;max_iterations=100;max_change=3f50624dd2f1a9fc;precision_as_displayed=false";

    // The first package, as the generator wrote it: its stored workbook part declares
    // date1904="1", iterate="1" and fullPrecision="0".
    let declaring = dc_hqcv_support::package(dc_hqcv_support::CALC_PR);
    let (workbook_pr, calc_pr) = declared_elements(&declaring);
    assert!(workbook_pr.contains(r#" date1904="1""#), "{workbook_pr}");
    let calc_pr = calc_pr.expect("package 1's workbook part holds calcPr");
    assert!(calc_pr.contains(r#" iterate="1""#), "{calc_pr}");
    assert!(calc_pr.contains(r#" fullPrecision="0""#), "{calc_pr}");

    let (mut host, sheet) = open_package(declaring, HostOptions::default());
    assert!(host.declared_date1904());
    let context = host.recalc_context();
    assert_eq!(run_fingerprint(&context), applied_fingerprint);
    assert_eq!(context, applied);
    note!(
        "ACCEPT-NOTE: {CASE}: package 1's stored workbook part declares {workbook_pr} and {calc_pr}; the host reads the declared date system (declared_date1904={}) and has no record of calcPr, which calc-doc does not read; applied: {}; run context fingerprint from the applied context alone: {}",
        host.declared_date1904(),
        context_text(&context),
        run_fingerprint(&context)
    );

    // Opened, nothing is calculated and the package caches no result.
    let awaiting = "stale last none none awaiting-recalc";
    let opened: Vec<(String, String)> = [
        ("A1", "literal 1.25"),
        ("B1", awaiting),
        ("A2", awaiting),
        ("B2", "empty"),
        ("A3", awaiting),
        ("B3", "empty"),
    ]
    .iter()
    .map(|(a1, text)| ((*a1).to_owned(), (*text).to_owned()))
    .collect();
    assert_eq!(described_a1_b3(&host, sheet), opened);

    // No iteration: the recalculation is refused for the circular reference at B1, the only cell
    // on a cycle or reading one, although calcPr declares iterate="1".
    assert_eq!(
        step(&mut host, WorkBudget::UNLIMITED, &mut Unobserved),
        HostProgress::Failed(RecalcFailed::Refused(StartError::Cycle {
            cells: vec![cell(sheet, "B1")],
        }))
    );
    assert_eq!(host.recalc_context(), applied);

    // Clearing B1 breaks the cycle (revision 1). The next recalculation takes tick 1 (the refused
    // one began none) and publishes at full precision: A2 = 1.25*1 = 1.25 and A3 = A2*2 = 2.5.
    // A2's cell format names number format `0`, but calc-doc loads no number format, so this
    // shows full-precision results, not that the host ignores a format it reads.
    let receipt = dispatch(
        &mut host,
        HostCommand {
            base: AuthoredRevision::new(0),
            edits: vec![CellEdit::Clear {
                area: GridArea::cell(cell(sheet, "B1")),
            }],
        },
    )
    .expect("the edit commits");
    assert_eq!(receipt.revision(), AuthoredRevision::new(1));
    let (revision, tick, published) =
        delta_cells(&step(&mut host, WorkBudget::UNLIMITED, &mut Unobserved));
    assert_eq!((revision, tick), (1, 1));
    assert_eq!(
        sorted(published.iter().map(|(at, _)| *at).collect()),
        sorted(vec![cell(sheet, "A2"), cell(sheet, "A3")])
    );
    let calculated: Vec<(String, String)> = [
        ("A1", "literal 1.25"),
        ("B1", "empty"),
        ("A2", "calculated 1.25 r1 t1 fast"),
        ("B2", "empty"),
        ("A3", "calculated 2.5 r1 t1 fast"),
        ("B3", "empty"),
    ]
    .iter()
    .map(|(a1, text)| ((*a1).to_owned(), (*text).to_owned()))
    .collect();
    assert_eq!(described_a1_b3(&host, sheet), calculated);
    assert_eq!(host.recalc_context(), applied);
    assert!(host.declared_date1904());
    note!(
        "ACCEPT-NOTE: {CASE}: package 1 observed: the circular reference B1 = B1+1 was refused (StartError::Cycle at B1), not iterated; after B1 was cleared, A2 = A1*1 calculated 1.25 and A3 = A2*2 calculated 2.5, published at full precision (A2's cell format names number format 0, which calc-doc does not load, so this does not show the host ignoring a format it reads); the date system was not observed: no calculation here reads or returns a serial date, so date1904=false is the host's report, not a measured behaviour"
    );

    // The second package: the same workbook part with no calcPr, opened under an Exact numeric
    // mode. The applied date system, iteration and precision, and so the fingerprint, are the
    // same; the numeric mode, which the fingerprint does not name, is the one the host was opened
    // with, and it is the verdict library's numeric mode type.
    let plain = dc_hqcv_support::package("");
    let (workbook_pr, calc_pr) = declared_elements(&plain);
    assert!(workbook_pr.contains(r#" date1904="1""#), "{workbook_pr}");
    assert_eq!(calc_pr, None);
    let target = NumericTargetId::new("16.0.0.0", "channel", "compatibility", "x86-64")
        .expect("a target with four parts");
    let exact = HostOptions {
        numeric: NumericMode::Exact(target),
        ..HostOptions::default()
    };
    let (host, _) = open_package(plain, exact.clone());
    assert!(host.declared_date1904());
    let context = host.recalc_context();
    assert_eq!(
        context,
        RecalcContext {
            numeric: exact.numeric.clone(),
            ..applied
        }
    );
    assert_eq!(run_fingerprint(&context), applied_fingerprint);
    note!(
        "ACCEPT-NOTE: {CASE}: package 2's stored workbook part declares {workbook_pr} and no calcPr; the host reads declared_date1904={}; applied: {}; run context fingerprint from the applied context alone: {}",
        host.declared_date1904(),
        context_text(&context),
        run_fingerprint(&context)
    );
}
